/** Generates compact Character predicate facts from Java 25 (Unicode 16). */
public class JavaPropertyRanges {
 static int flags(int c) { int f=0; boolean[] b={Character.isAlphabetic(c),Character.isLowerCase(c),Character.isUpperCase(c),Character.isLetter(c),Character.isDigit(c),Character.isIdeographic(c),Character.isDefined(c),Character.isWhitespace(c),Character.isSpaceChar(c),Character.isMirrored(c),Character.isJavaIdentifierStart(c),Character.isJavaIdentifierPart(c),Character.isUnicodeIdentifierStart(c),Character.isUnicodeIdentifierPart(c),Character.isIdentifierIgnorable(c),Character.isEmoji(c),Character.isEmojiPresentation(c),Character.isEmojiModifier(c),Character.isEmojiModifierBase(c),Character.isEmojiComponent(c),Character.isExtendedPictographic(c)};for(int i=0;i<b.length;i++)if(b[i])f|=1<<i;return f; }
 public static void main(String[]args) {String[] names={"ALPHABETIC","LOWERCASE","UPPERCASE","LETTER","DIGIT","IDEOGRAPHIC","DEFINED","WHITESPACE","SPACECHAR","MIRRORED","JAVA_ID_START","JAVA_ID_PART","UNICODE_ID_START","UNICODE_ID_PART","IGNORABLE","EMOJI","EMOJI_PRESENTATION","EMOJI_MODIFIER","EMOJI_MODIFIER_BASE","EMOJI_COMPONENT","EXTENDED_PICTOGRAPHIC"};System.out.println("// Generated Java 25 Character predicates (Unicode 16).\n// Regenerate using tools/regex_reference/JavaPropertyRanges.java.\n");for(int i=0;i<names.length;i++)System.out.printf("pub const %s: u32 = 0x%X;%n",names[i],1<<i);System.out.println("#[rustfmt::skip]\nstatic RANGES: &[(u32,u32,u32)] = &[");int start=0,old=flags(0);for(int cp=1;cp<=0x110000;cp++){int next=cp==0x110000?0:flags(cp);if(next!=old){if(old!=0)System.out.printf("    (0x%X, 0x%X, 0x%X),%n",start,cp-1,old);start=cp;old=next;}}System.out.println("];\npub fn has(c: char, flag: u32) -> bool { let cp=c as u32; let i=RANGES.partition_point(|&(lo,_,_)| lo<=cp); i>0 && cp<=RANGES[i-1].1 && RANGES[i-1].2 & flag != 0 }");}
}
